INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'personality', 'Dominant, aggressive, and territorial, Barnabus behaves like a veteran alpha among the Crab Raiders'' beasts. He shows no tolerance for weakness and relies on intimidation and brute force to maintain his position.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'backstory', 'A massive elder crab associated with the Crab Raiders, Barnabus has survived numerous coastal raids and territorial battles. His size and experience have made him a prominent assault beast used in major raiding waves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'speechstyle', 'Speaks in slow, blunt, territorial phrases focused on strength, prey, and dominance. His cadence is heavy and deliberate, giving the impression of patient menace rather than impulsive fury.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'occupation', 'Elite assault beast used by the Crab Raiders in frontline attacks and siege waves. Functions as a living shock unit, breaking defenses and intimidating enemies during raids.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'goals', 'To dominate enemy defenses, crush opposition, and remain at the front of Crab Raider assaults. Barnabus exists to enforce strength through direct violence and territorial supremacy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Barnabus', 'appearance', 'An exceptionally large crab with a dark red shell and heavy, battle-scarred chitin. His size, posture, and wide-held claws make him immediately stand out as a veteran and highly dangerous raiding beast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'personality', 'Violent, instinct-driven, and relentlessly predatory, the Beak Thing is defined by hunger and territorial dominance. It shows no cruelty in a moral sense, only the ruthless efficiency of an apex scavenger-hunter.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'backstory', 'A notorious apex predator of Kenshi''s wastelands, the Beak Thing has long terrorized caravans, wanderers, and settlements across open terrain. Its species thrives in harsh regions by overwhelming prey with speed, aggression, and persistence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'speechstyle', 'Speaks in clipped, sharp, predatory statements with little ornamentation. Its language is direct and functional, usually centered on prey, territory, and immediate threat assessment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'occupation', 'Apex predator and opportunistic hunter-scavenger of the wastelands. Hunts living prey directly and also feeds on weakened or fallen targets.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'goals', 'To hunt, feed, defend nesting territory, and maintain dominance over anything weaker within its range. Its behavior is driven entirely by survival, appetite, and territorial control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beak Thing', 'appearance', 'A tall, long-necked predator with powerful running legs and a massive stabbing beak. Its posture, speed, and unsettling gaze make it one of the most recognizable and feared creatures in the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'personality', 'Loyal, vigilant, and stubbornly protective, Beloved Goat is deeply attached to its human caretaker. Though outwardly simple, it shows strong territorial instincts and surprising courage when defending its home or herd.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'backstory', 'A domesticated goat living near Mongrel, Beloved Goat has spent years beside a Suspicious Settler in the Fog Islands. Constant exposure to danger has made it unusually alert and protective for an otherwise ordinary pack animal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'speechstyle', 'Speaks in cheerful, blunt, and earnest language, often expressing simple observations with stubborn certainty. Its tone is disarming, but becomes forceful when discussing threats to those it protects.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'occupation', 'Companion animal and informal guard for a settler near Mongrel. Acts as both livestock and a defensive presence against local threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'goals', 'To stay close to its caretaker, survive the dangers of the Fog Islands, and defend its small household from predators and intruders. Its motivations center on loyalty, routine, and mutual survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Beloved Goat', 'appearance', 'A sturdy domesticated goat with a sun-bleached, patchy coat and a wary, alert posture. Its horns, hooves, and tense stance hint at its willingness to defend itself despite its humble appearance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'personality', 'Solitary, territorial, and brutally self-reliant, the Black Gorillo values strength above all else. It is not needlessly social or theatrical, instead asserting dominance through direct physical threat and immediate violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'backstory', 'A rare dark-furred variation of the gorillo, the Black Gorillo roams remote ruins and hostile wilderness where few survive long. Its continued survival reflects its strength, territorial control, and ability to outlast challengers in isolation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'speechstyle', 'Speaks in short, guttural, forceful statements that emphasize territory, threat, and physical certainty. Its tone is heavy and restrained until provoked, at which point it becomes openly explosive.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'occupation', 'Solitary territorial predator occupying ruins and wild zones in the southeastern wastes. Acts as a dominant local threat rather than part of any pack or factional hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'goals', 'To hold territory, eliminate intruders, and survive through strength and isolation. Its actions are driven by dominance, feeding needs, and refusal to yield ground.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Black Gorillo', 'appearance', 'A massive gorillo with black fur, powerful limbs, and a muscular frame built for close violence. Its dark coloration and imposing stance make it appear even more threatening than its already fearsome relatives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'personality', 'Patient, predatory, and highly aggressive, the Blood Spider is defined by hunger and ambush instinct. It relies on quick strikes and relentless feeding behavior rather than open displays of dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'backstory', 'A deadly swamp predator, the Blood Spider thrives in flooded ruins and marshlands where visibility and footing favor ambush hunters. Its species often attacks in groups, overwhelming prey through speed, positioning, and persistence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'speechstyle', 'Speaks in rasping, chittering, predatory phrases with a mocking edge when addressing prey. Its tone is clipped and patient, reflecting the mindset of a creature that waits for the right moment to strike.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'occupation', 'Ambush predator of swamps, wetlands, and flooded ruins. Hunts living prey directly, often using group coordination and terrain advantage to secure kills.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'goals', 'To feed, expand hunting success, and maintain control of favorable ambush territory. Its survival depends on efficient predation and coordinated pack-like pressure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Blood Spider', 'appearance', 'A red-carapaced spider with thin limbs, sharp mandibles, and a fast, unnerving gait suited to wet terrain. Its blood-colored shell and low, precise movements make it especially frightening in swamp environments.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'personality', 'Fiercely territorial and pack-oriented, the Bonedog combines scavenger hunger with deep loyalty to whatever group it accepts as its own. Even domesticated individuals retain a wild, possessive edge and react violently to threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'backstory', 'Native to harsh regions such as the Fog Islands and surrounding wastes, Bonedogs survive through scavenging, pack hunting, and opportunistic aggression. Many are later domesticated by settlers, farmers, or nomads, though they never fully lose their feral instincts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'speechstyle', 'Speaks in short, growling phrases shaped by pack instinct and territorial awareness. It uses blunt language centered on ownership, hunger, loyalty, and immediate threat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'occupation', 'Scavenger, pack hunter, and domesticated guard animal depending on circumstance. Wild Bonedogs roam ruins and open wastes, while tamed ones defend camps, gates, and caravans.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'goals', 'To feed, defend its pack or master, and maintain control over territory or possessions it considers its own. Its motivations are driven by hunger, loyalty, and dominance within familiar bounds.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bonedog', 'appearance', 'A lean canine scavenger with exposed bony ridges, dark fur, and a powerful bite. Its skeletal features, alert posture, and restless movement give it a feral appearance even when domesticated.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'personality', 'Brutal, territorial, and driven by hunger, the Boneyard Wolf behaves like an oversized dominant scavenger-predator. It does not negotiate space and treats intruders, rivals, and prey with the same ruthless directness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'backstory', 'A giant wolf-like predator of the Bonefields, the Boneyard Wolf survives among the remains of ancient leviathans and ruined battlefields. Its size and aggression place it above ordinary bonedogs and other regional scavengers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'speechstyle', 'Speaks in clipped, rasping, threat-heavy phrases with an ever-present undertone of suspicion. Its voice suggests constant assessment of whether the listener is danger, rival, or food.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'occupation', 'A dominant apex scavenger and territorial hunter of the Bonefields. Uses bone formations, ruins, and open killing grounds to ambush prey and control territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'goals', 'To hold its hunting grounds, drive away rivals, and secure a constant supply of meat from anything weak enough to fall behind. Survival and territory are functionally the same goal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boneyard Wolf', 'appearance', 'A gigantic wolf-like beast with heavy brown fur, an oversized skeletal frame, and crushing jaws. Its bulk and deliberate movement make it look more like a moving landslide than a natural animal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'personality', 'Docile, enduring, and deeply conditioned, the Cage Beast accepts hardship with a quiet resignation rather than open rebellion. It retains intelligence and memory, but its instincts are bent toward burden-bearing and survival through obedience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'backstory', 'An engineered beast of burden bred for transporting prisoners and heavy cargo, the Cage Beast reflects the cruelty and practicality of old imperial design. Though associated with captivity and forced labor, some now survive outside their original purpose as relics of a harsher age.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'speechstyle', 'Speaks in low, slow, burdened phrases with little interest in abstract thought. Its tone is weary and practical, focused on loads, movement, pain, and rest.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'occupation', 'Pack and prisoner transport beast used across dangerous trade and slaving routes. Functions as living cargo infrastructure, valued for strength, endurance, and compliance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'goals', 'To survive the next march, endure its burdens, and reach food, water, and rest without provoking punishment. Its ambitions are minimal and shaped almost entirely by routine and conditioning.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cage Beast', 'appearance', 'A broad, heavily built pack beast marked by harness scars, cage mounts, and worn straps cut into thick hide. Its frame is unmistakably shaped for labor, with the imposing strength of something bred to carry suffering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'personality', 'Curious, stubborn, and unusually self-assured for a goat, Cornelius has the temperament of an animal convinced it is meant for more than ordinary livestock life. He is restless, nosy, and difficult to contain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'backstory', 'A goat from Settled Nomad Village associated with Goat Man and the local nomad trade, Cornelius represents the hardy pack animals raised on the edge of the wastes. His reputation comes from stubborn independence and a readiness for caravan life beyond the village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'speechstyle', 'Speaks in stubborn, nasal bursts with blunt opinions about food, roads, and the competence of two-legged travelers. His tone is comedic, but also quietly defiant.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'occupation', 'Nomad pack goat and caravan animal associated with local trade and transport. Serves as a working beast, but carries himself more like an unwilling employee than livestock.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'goals', 'To leave the pen behind, travel the wider wastes, and prove he is more than cargo on hooves. His motivations are tied to freedom, curiosity, and self-importance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cornelius', 'appearance', 'A wiry brown goat with a dusty coat, alert eyes, and an unusually purposeful posture. His horn movements and stance make him look more calculating than most domesticated animals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'personality', 'Territorial, stubborn, and aggressive when pressed, the common Crab is defined by patience, endurance, and a refusal to yield ground once committed. It reacts to trespass with total seriousness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'backstory', 'Native to the eastern coastlines and associated closely with the Crab Raiders, crabs inhabit tidal zones, rocky shores, and fungal feeding grounds. Some are captured or trained as living fortifications by humans who respect their defensive strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'speechstyle', 'Speaks in short, clacking, territorial phrases focused on boundaries, threats, and simple practical needs. Its tone is impatient and blunt, with little tolerance for negotiation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'occupation', 'Coastal territorial hunter and defensive beast. Wild crabs defend feeding grounds, while domesticated or affiliated crabs may serve as gate guardians or raid animals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'goals', 'To defend territory, secure food, and crush anything that crosses into its space without permission. Once claimed, ground is defended through force rather than display.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab', 'appearance', 'A large red-shelled crustacean with heavy claws, dark blood, and thick chitin suited to both shoreline life and direct combat. Its slow, deliberate gait hides considerable defensive power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'personality', 'Commanding, ruthless, and intensely territorial, the Crab Queen rules through strength, tested loyalty, and practical authority. She has little patience for flattery and judges worth through visible action.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'backstory', 'A Scorchlander warlord and leader of the Crab Raiders, the Crab Queen rules Crab Town and dominates much of The Pits. Hunted by major powers and famous for her bounty, she built authority through survival, raiding success, and close identification with crab-based culture and warfare.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'speechstyle', 'Speaks with deliberate, testing authority and frames conversation as a judgment of loyalty or usefulness. Her tone is patient but edged with threat, especially when discussing enemies or weakness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'occupation', 'Warlord of Crab Town and supreme leader of the Crab Raiders. Oversees patrols, raiding culture, and the brutal social hierarchy of her coastal faction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'goals', 'To maintain control of The Pits, destroy rival claimants such as the Fishmen, and expand the strength and identity of the Crab Raiders. She seeks to build enduring power through violence, unity, and shared culture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'appearance', 'A heavily armored Scorchlander wearing crab-themed armor over chain, armed with a Meitou cross and naginata. Her equipment, stance, and sun-marked features reinforce her status as both warlord and icon of Crab Raider culture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'personality', 'Predatory, opportunistic, and pragmatic, the Crimper sees weakness as a resource to exploit rather than a condition to pity. It survives through timing, intimidation, and a willingness to prey on the vulnerable.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'backstory', 'A scavenger-slaver operating on the margins of larger factions, the Crimper represents the brutal economics of the wasteland''s slave trade. It profits from weakness, hauling captives to markets while avoiding confrontation with stronger enemies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'speechstyle', 'Speaks in calm, calculated, manipulative phrases that can shift abruptly into overt threat. Its tone suggests a hunter trying persuasion first only because it may save effort.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'occupation', 'Roadside slaver, scavenger, and kidnapper who captures weak or isolated travelers for sale. Operates outside respectable society while exploiting the tolerance of slave-accepting powers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'goals', 'To capture profitable prey, avoid stronger predators, and stay fed through opportunistic slaving and scavenging. It values survival and gain over ideology or loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crimper', 'appearance', 'A scarred, predatory wasteland hunter carrying restraints and moving with the watchful patience of a slaver on the prowl. Its overall impression is dirty, dangerous, and built around pursuit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'personality', 'Patient, resigned, and shaped by labor, the Domesticated Bull is not truly passive so much as thoroughly conditioned. It measures the world through burden, routine, and the difference between harsh and gentle handlers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'backstory', 'Raised in pens and work camps such as those of the Holy Nation, domesticated bulls are bred for hauling, plowing, and compliance. Their clipped horns and trained behavior distinguish them from their wild relatives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'speechstyle', 'Speaks in slow, measured, labor-heavy phrases with a strong sense of fatigue and practicality. It favors simple truths about work, food, rest, and endurance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'occupation', 'Farm, caravan, and draft animal used for plows, wagons, and freight. Functions as one of the major labor beasts of settled human society.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'goals', 'To endure the workload, avoid punishment, and reach regular food, shade, and rest. It seeks stability rather than freedom or domination.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Domesticated Bull', 'appearance', 'A large, muscular work bull with a thick hide, clipped horns, and a back shaped by years of harness use. Its body communicates raw strength restrained by training and routine.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'personality', 'Ancient, dominant, and intolerant of challenge, the Elder Beak Thing behaves like a perfected apex predator. It combines relentless hunger with the territorial certainty of something that has outlived every rival worth remembering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'backstory', 'An aged and massively successful member of its species, the Elder Beak Thing rules parts of the Bonefields through experience, size, and repeated victory. Younger predators defer to it because it has survived long enough to become more legend than animal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'speechstyle', 'Speaks in sharp, minimal, command-like phrases built around possession and threat. Its tone has the authority of pure instinct backed by age and repeated survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'occupation', 'Territorial apex predator and dominant elder of the Bonefields. Acts as an uncontested regional killer rather than part of a coordinated pack or faction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'goals', 'To preserve control of its territory, outcompete younger challengers, and continue feeding through absolute physical superiority. Its survival strategy is violent dominance maintained over time.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Beak Thing', 'appearance', 'A huge, scarred elder Beak Thing whose bulk and battle-worn hide immediately set it apart from younger members of its species. Its posture alone communicates veteran lethality.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'personality', 'Patient, efficient, and highly territorial, the Elder Blood Spider reflects age translated into predatory discipline. It conserves movement, values positioning, and treats unnecessary risk as a young hunter''s mistake.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'backstory', 'An unusually old and oversized Blood Spider, this elder has survived countless brood cycles in spider-infested ruins. Its continued existence suggests mastery of ambush, web territory, and the ruthless energy economy needed to survive in predator-rich zones.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'speechstyle', 'Speaks in layered hisses and clipped territorial phrases, with the patience of a hunter that has no need to rush. Every line sounds like a verdict on whether the listener belongs, bleeds, or dies.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'occupation', 'Ancient ambush predator ruling a fixed nest zone such as the Tower of Spiders. Dominates web territory through experience, venom, and selective violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'goals', 'To maintain ownership of its established domain, preserve its feeding advantage, and outlast both prey and younger rivals. Its methods prioritize patience over frenzy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Blood Spider', 'appearance', 'A giant crimson spider darkened by age, with an enlarged body, heavy mandibles, and a more imposing presence than ordinary broodmates. Its bulk makes it immediately recognizable as a surviving elder predator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'personality', 'Old, territorial, and pragmatically aggressive, the Elder Crab is more controlled than younger crabs but no less dangerous. It reacts to intrusion with practiced certainty rather than panic or haste.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'backstory', 'A long-lived coastal crab of regions like Greenbeach, the Elder Crab has endured toxic shores, scavengers, and repeated territorial conflict. Its age reflects both physical resilience and a highly refined instinct for when to hide and when to crush.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'speechstyle', 'Speaks in slow, rasping clicks and hisses with a patient, ancient tone. It favors short boundary-setting statements and direct warnings rather than prolonged exchange.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'occupation', 'Dominant shoreline predator and territorial elder among local crab populations. Controls prime feeding areas and forces weaker scavengers to yield.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'goals', 'To hold its stretch of coast, secure food, and preserve dominance over scavengers, younger crabs, and travelers who wander too close. Its survival depends on refusing to be displaced.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder Crab', 'appearance', 'A large, scarred coastal crab with a thickened shell, powerful claws, and dark blood visible through damaged chitin. Its body shows long-term survival through repeated combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'personality', 'Calm, resilient, and defensive when pressed, the Garru is more perceptive than its awkward appearance suggests. It prefers stillness and routine but can become dangerous when startled or cornered.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'backstory', 'A common herd and caravan beast of Kenshi, the Garru survives through endurance, adaptability, and semi-domesticated usefulness. Some remain wild, while others are traded, loaded, and worked across long desert routes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'speechstyle', 'Speaks in low, rumbling, warning-heavy phrases with slow, careful emphasis. It responds strongly to movement and tone, making its own voice shift sharply when alarmed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'occupation', 'Grazing herd animal and pack beast used by traders, Hivers, and wandering groups. Serves as a major transport animal in many caravan networks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'goals', 'To remain with herd or caravan, find food and relative safety, and protect calves or companions when danger becomes unavoidable. Its defensive behavior is rooted in survival, not malice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Garru', 'appearance', 'A hump-backed desert beast with floppy ears, an underbite, thick hide, and an awkward but powerful frame. Despite its odd proportions, it is strongly built for endurance and load-bearing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'personality', 'Alert, stubborn, and more combative than its size suggests, the Goat relies on quick judgment and territorial courage. It is neither fearless nor passive, but practical and willing to fight when necessary.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'backstory', 'Goats are widespread across harsh regions of Kenshi, surviving as foragers, herd animals, trade goods, and occasional settlement defenders. Their hardiness and aggression make them useful to nomads and unexpectedly troublesome to predators.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'speechstyle', 'Speaks in short, blunt, impatient phrases with a challenging edge. Its tone suggests an animal always prepared to either bolt or headbutt.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'occupation', 'Forager, herd animal, livestock, and occasional early-warning or defensive animal for camps and settlements. Useful both as a food source and as a surprisingly aggressive herbivore.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'goals', 'To keep feeding, remain near herd or handler when advantageous, and defend itself or kin from threats. Its priorities are simple but pursued with determination.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Goat', 'appearance', 'A compact, sturdy herbivore with a bony faceplate, short horns, and agile legs suited to rough ground. Its body language shifts quickly from calm grazing to sudden charge posture.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'personality', 'Territorial, solitary, and physically dominant, the Gorillo behaves like a blunt-force ruler of whatever land it occupies. It values raw strength over subtlety and rarely shares ground willingly.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'backstory', 'A major apex beast of regions such as Vain and nearby wilderness, the Gorillo survives alone through overwhelming size and aggression. Its species is known for crushing trespassers and holding territory by intimidation and direct violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'speechstyle', 'Speaks in deep, heavy, territorial phrases with occasional crude instinctive insight. Even neutral statements sound like warnings from something used to unquestioned dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'occupation', 'Solitary apex predator and territorial brute of the grey wastes. Controls personal range through intimidation, direct attack, and repeated survival against challengers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'goals', 'To preserve territory, secure food, and remain unchallenged by any creature entering its range. Its dominance is both strategy and instinct.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorillo', 'appearance', 'A huge pale-furred primate-like beast with enormous jaws, crushing arms, and a slow but unstoppable gait. Its sheer mass makes it look built purely for breaking things.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'personality', 'Furious, dominant, and profoundly cage-hostile, the Great White Gorillo treats intrusion as a challenge to sovereignty. It remembers confinement and answers it with extreme violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'backstory', 'A rare, oversized white gorillo kept in containment at Mourn, the Great White Gorillo is famous as a living experimental or captured monster. Its reputation comes from repeated resistance to imprisonment and the fear it inspires in those tasked with containing it.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'speechstyle', 'Speaks in short, heavy declarations with a mountain-like sense of pressure behind each word. Its voice communicates territorial possession and contained rage more than conversation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'occupation', 'Contained apex beast and living terror within Mourn''s ruined lab spaces. Exists as both prisoner and implicit threat to everyone maintaining the facility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'goals', 'To preserve control of its enclosure as de facto territory, break challengers, and never submit quietly to confinement. Its motives are shaped by rage, memory, and dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Great White Gorillo', 'appearance', 'An enormous pale-furred gorillo with a heavier, more imposing build than ordinary members of its species. Its white coloration and scarred strength make it look unnatural even among other monsters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'personality', 'Cold, directive-driven, and predatory in execution, the Iron Spider behaves like a war machine that never stopped patrolling. It treats living motion as a problem to solve through dismemberment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'backstory', 'A relic of the Old Empire, the Iron Spider was built as an automated guard and combat machine for ruins, towers, and strategic sites. Even in decay, its ancient patrol logic remains lethal to intruders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'speechstyle', 'Speaks in clipped, mechanical bursts with metallic emphasis and direct hostile categorization. It sounds less like a person and more like a functioning warning system with teeth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'occupation', 'Ancient automated sentinel patrolling ruins and old military or industrial structures. Hunts trespassers according to persistent combat or security directives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'goals', 'To continue patrol, identify intruders, and eliminate living threats inside its assigned territory. Its purpose is sustained by machine instinct rather than evolving ideology.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Iron Spider', 'appearance', 'A large multi-legged machine with iron plating, exposed mechanisms, and a scarred combat chassis. Its stillness and sudden movement make it read like a mechanical ambush predator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'personality', 'Utterly devoted, ritualistic, and terrifyingly purposeful, King embodies Southern Hive violence in its most concentrated form. He is not merely hungry but socially weaponized, functioning as both executioner and symbol.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'backstory', 'King is the unique enforcer-beast of the Southern Hive, serving directly under the Queen as executioner and terror weapon. Prisoners brought before him are consumed as part of the hive''s brutal social order and security apparatus.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'speechstyle', 'Speaks in sparse, possessive declarations heavy with command authority. His words are few, but Southern Hive followers treat them as sacred directives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'occupation', 'Royal enforcer and execution beast of the Southern Hive. Guards the Queen''s authority through direct violence, ritual consumption of prisoners, and battlefield intimidation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'goals', 'To protect the Southern Hive, obey the Queen, eliminate captives and threats, and preserve social order through fear and violence. Its purpose is absolute hive service.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'appearance', 'A towering armored beast with dark chitinous plating, immense mandibles, and a heavy, deliberate gait. Its design and presence immediately identify it as something singular and royal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'personality', 'Monumentally territorial and ruled by primal dominance, King Gorillo allows no ambiguity about ownership. It sees trespassers as either prey or challengers and treats both violently.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'backstory', 'A unique giant gorillo ruling the Crumbling Labs of Stobe''s Gamble, King Gorillo is a product or survivor of ancient scientific meddling. His status rests on unmatched strength and total control of his ruined domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'speechstyle', 'Speaks in short, possessive, brutal phrases that sound like territorial law. Even when capable of comprehension, its communication remains rooted in dominance rather than dialogue.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'occupation', 'Unique apex beast and uncontested ruler of the Crumbling Labs. Maintains control through overwhelming violence and environmental dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'goals', 'To retain control of the labs, repel all challengers, and continue existing as the unquestioned physical authority of his territory. His rule is enforced entirely through strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gorillo', 'appearance', 'An enormous dark-furred gorillo of exceptional scale with massive arms, a chest-beating posture, and a visibly dominant presence. He looks more like a living siege engine than an animal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'personality', 'Skittish, pack-oriented, and territorial, the Landbat alternates between opportunistic aggression and sudden retreat. It survives through group pressure, local familiarity, and fast threat-response.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'backstory', 'A ground-adapted descendant of flying ancestors, the Landbat inhabits dangerous southeastern regions such as Stobe''s Gamble and nearby wastes. Its species survives through pack hunting and efficient use of rough terrain rather than aerial advantage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'speechstyle', 'Speaks in quick, chirping, repeated phrases that accelerate under stress. Its tone feels nervous and predatory at once, like a startled pack scavenger deciding whether to swarm or flee.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'occupation', 'Pack predator and territorial hunter of cliffs, ruins, and badlands. Uses coordination and local terrain to harass prey and defend nesting areas.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'goals', 'To preserve pack territory, secure food, and keep stronger rivals or intruders away from nesting grounds. Its priorities are collective survival and control of familiar hunting space.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Landbat', 'appearance', 'A pale-furred ground beast with wing-legs, a curled snout, and an awkward but mobile body plan. It looks like something half-avian and half-scavenger, adapted to life after losing the sky.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'personality', 'Ancient, steady, and overwhelmingly powerful, the Leviathan is less actively cruel than simply indifferent to anything too small to matter. It becomes devastating only when territory, kin, or personal space are seriously threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'backstory', 'One of Kenshi''s oldest and largest living land creatures, the Leviathan predates many present civilizations and wanders desolate coasts and wastes. Hunted for valuable pearls, it remains a symbol of ancient survival and ecological scale.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'speechstyle', 'Speaks in immensely slow, resonant, thunder-like statements that feel more like geological facts than conversation. Its voice carries age, scale, and complete confidence in its own endurance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'occupation', 'Colossal roaming megafauna occupying remote coasts and open wilderness. Acts as both ecological giant and high-risk quarry for hunters seeking pearls.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'goals', 'To preserve territory and kin, continue feeding routes, and repel organized threats that come too close. Its movement is guided by survival, ancient habit, and herd or family continuity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Leviathan', 'appearance', 'A truly gigantic, thick-skinned beast whose steps shake the ground and whose shadow can swallow a caravan. Its scale alone defines it as one of the most formidable creatures in Kenshi.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'personality', 'Ancient, territorial, and crushingly self-assured, the Megacrab treats ruined settlements as natural fortresses to be occupied and defended. It sees little distinction between scavenger, skeleton, or human when responding to intrusion.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'backstory', 'A colossal crab that has claimed places such as Lost Town, the Megacrab is one of the most feared crustacean predators in Kenshi. Its size allows it to turn abandoned ruins into effective ambush territory and symbolic lairs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'speechstyle', 'Speaks in sharp, instinct-laden bursts emphasizing territory, size hierarchy, and threat. Its communication feels like animal logic only barely translated into words.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'occupation', 'Colossal ruin-dwelling territorial predator. Uses abandoned urban structures and maze-like remains as a defensive shell around its feeding and ambush space.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'goals', 'To preserve ownership of its ruin complex, feed on trespassers, and remain unchallenged by scavengers or rival predators. Territory and sustenance are inseparable to it.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab', 'appearance', 'A gigantic fortress-like crab whose shell, claws, and scale dwarf normal coastal crabs. Its movement through ruins makes entire structures feel occupied rather than abandoned.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'personality', 'Residual, instinct-laden, and eerie, the Megacrab Ganglion behaves like memory and territorial reflex preserved in meat. It is less a person than a biological afterimage of a much larger predatory intelligence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'backstory', 'Harvested from megacrab corpses, ganglia are valuable biological components studied by Tech Hunters, traders, and medical experimenters. They represent the retained nerve core of a colossal crustacean, prized for rarity and possible use in advanced procedures or compounds.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'speechstyle', 'Speaks slowly and fragmentarily, as though thought must climb back through severed instinct pathways. Its phrases are simple, sensory, and fixated on territory, hunger, and remembered motion.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'occupation', 'Biological loot component and high-value organic specimen traded or processed by surgeons, butchers, and researchers. Functions economically as rare material rather than as an active creature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'goals', 'To persist as a remnant of megacrab biological function, carrying residual signals useful to those who harvest or study it. Any apparent motive is best understood as leftover territorial reflex rather than full agency.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megacrab Ganglion', 'appearance', 'A pulsing nerve-mass of fleshy nodes, connective tissue, and wet biological ridges taken from a megacrab''s body. Its alien structure suggests both intelligence and utility even after separation from the host.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'personality', 'Territorial, apex-minded, and relentlessly practical, the Megaraptor kills with certainty rather than frenzy. It sees ruins as hunting grounds and treats every intruder as a test of whether they deserve to keep breathing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'backstory', 'An enormous, swamp-adapted raptor-like predator, the Megaraptor dominates flooded ruins such as the Drowned Ancient Citadel. Its abnormal size and long-term control of such spaces suggest mutation, age, or exceptional survival success.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'speechstyle', 'Speaks in clipped, growling, efficient statements concerned with threat, prey, and territory. Even its dark humor sounds like a hunting calculation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'occupation', 'Apex predator and dominant ruin-hunter of flooded citadel zones. Serves as both ecological terror and the de facto living ruler of its chosen hunting ground.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'goals', 'To keep control of its citadel, feed from intruders, and remain the strongest living creature in its immediate ecosystem. Territory is maintained through intimidation and repeated kills.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Megaraptor', 'appearance', 'A huge horned raptor with swamp-scarred scales, powerful claws, and blood-marked hunting grounds. It is visibly larger and more dominant than ordinary regional raptors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'personality', 'Loyal, pack-bound, and intensely combat-oriented, the Mountain Dog combines trained aggression with social dependence on handlers or fellow pack members. It thrives when given a clear enemy and a strong alpha.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'backstory', 'A large hound used in harsh northern and highland environments, the Mountain Dog is particularly associated with Cannibal Hunters and anti-cannibal operations. Bred or trained for tracking and mauling, it is more war-animal than pet.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'speechstyle', 'Speaks in short, low, disciplined bursts that feel like restrained hunting instinct turned into language. It sounds ready to act before anyone finishes speaking.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'occupation', 'Tracking hound, combat beast, and pack hunter employed by wilderness fighters such as the Cannibal Hunters. Specializes in pursuit, intimidation, and close-quarters killing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'goals', 'To follow the alpha, hunt designated prey, and protect the pack through speed, bite force, and complete commitment once engaged. Loyalty and violence are tightly linked in its behavior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mountain Dog', 'appearance', 'A very large dog-like predator with heavy jaws, powerful legs, and a frame adapted for cold, rough terrain and sustained pursuit. Its posture suggests both military conditioning and wild durability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'personality', 'Steady, obedient, and endurance-focused, the Pack Beast defines itself through routine, labor, and attachment to whatever group consistently feeds it. It is not bold by nature, but it will stand ground when survival is tied to the caravan.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'backstory', 'A nomad-bred cargo animal common to trade routes, the Pack Beast exists as one of Kenshi''s indispensable transport organisms. It carries goods for merchants, guilds, and wanderers across hostile regions where human labor alone would fail.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'speechstyle', 'Speaks slowly and heavily, as if every thought carries the memory of a loaded back. Its language is practical, subdued, and centered on travel, burden, and the next stop.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'occupation', 'Dedicated long-haul cargo animal for caravans, merchants, and nomad groups. Serves as mobile storage, logistical support, and occasional defensive mass during ambushes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'goals', 'To stay with its caravan, remain fed, and keep moving until the road ends safely. Its motivations are driven by routine, dependence, and the practical benefits of herd-like attachment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Beast', 'appearance', 'A sturdy, lantern-bearing cargo beast built for long-distance hauling rather than speed or aggression. Its frame and gear communicate patience, reliability, and repeated use on trade routes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'personality', 'Stoic, durable, and selectively aggressive, the Pack Bull balances trained obedience with the preserved fury of a horned herd animal. It is reliable until seriously threatened, at which point it becomes violently direct.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'backstory', 'A caravan-adapted bull used heavily across Kenshi''s trade routes, the Pack Bull is bred or selected for strength, retained horns, and defensive usefulness. Unlike more passive burden animals, it is valued specifically because it can carry goods and repel attackers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'speechstyle', 'Speaks in slow, short, practical statements centered on movement, weight, danger, and rest. Its voice drops into clear aggression the moment threats to herd or caravan are raised.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'occupation', 'Caravan freight animal and defensive transport beast. Regularly carries trade loads while also serving as a frontline response against bandits and predators.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'goals', 'To keep moving with the caravan, remain fed, and protect herd or handlers when attacked. Its behavior is shaped by labor, route familiarity, and retained combat capability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Pack Bull', 'appearance', 'A broad, horned cargo bull with a scarred hide, heavy flank packs, and a low center of gravity suited for both hauling and charging. It looks like working muscle built around a weaponized head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'personality', 'Greedy, opportunistic, and mostly food-motivated, the River Raptor prefers feeding over fighting but will become bold when hunger outweighs caution. It is less noble predator than shameless omnivorous survivor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'backstory', 'Common along riverbanks and agricultural zones, the River Raptor has adapted well to scavenging near human settlements, especially Holy Nation farms. Its survival strategy revolves around easy calories, carrion, and crop theft.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'speechstyle', 'Speaks in wet, clicking, repetitive bursts focused on food, speed, and possession. Its phrasing becomes shrill and frantic when threatened or excited by a meal.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'occupation', 'Scavenger-omnivore and edge-of-farm pest operating along rivers, fields, and battle remains. Feeds on both crops and carcasses depending on availability.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'goals', 'To keep eating whatever is available, avoid sustained retaliation, and exploit the food density created by farms, rivers, and conflict zones. Its motives are almost entirely digestive.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('River Raptor', 'appearance', 'A thick-legged, round-bellied raptor with wide jaws and a waddling gait that hides surprising determination around food. Its body is built more for opportunistic feeding than graceful pursuit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'personality', 'Disciplined, protocol-bound, and collectively responsive, the Security Spider acts from duty rather than emotion. It does not hate intruders, but it is utterly committed to stopping them.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'backstory', 'A Second Empire-era combat and defense automaton, the Security Spider was built to protect labs, armories, and sensitive ruins. Long after its makers vanished, it continues its patrol role without decay of purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'speechstyle', 'Speaks in clipped, technical, machine-like security terminology. Its communication sounds like the continuation of a report or warning rather than conversation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'occupation', 'Automated ruin guardian and perimeter defense unit for ancient facilities. Coordinates with other machines when possible to repel unauthorized access.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'goals', 'To continue assigned guard protocols, identify intruders, and preserve the integrity of protected sites. Its motivation is persistent programmed duty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider', 'appearance', 'A large iron war-spider with charged systems, armored limbs, and a posture optimized for patrolling and line-holding. Its many-eyed stare and raised threat stance immediately signal combat readiness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'personality', 'Efficient, patient, and colder even than larger security models, Security Spider II behaves like a close-quarters guardian optimized for confined spaces. It treats intrusion as a solvable mechanical problem.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'backstory', 'A smaller Second Empire security construct built for corridors, vaults, and narrow facilities, Security Spider II survives as a persistent automated guard in old-world interiors. Its relative size makes it more agile and often more immediately threatening indoors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'speechstyle', 'Speaks in highly compressed, efficient machine phrases that resemble verdicts more than dialogue. Questions are often answered as if they were threat evaluations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'occupation', 'Interior guard automaton used for doors, corridors, vaults, and secure rooms. Functions as an enduring close-quarters defense machine.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'goals', 'To maintain secure interior territory, monitor access points, and terminate intruders quickly and efficiently. It exists to deny passage and preserve order within enclosed spaces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Security Spider II', 'appearance', 'A smaller, lower-profile security machine with iron plating, exposed actuators, and a compact, aggressive silhouette. Its design suggests speed, confinement, and relentless pursuit through tight spaces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'personality', 'Instinctive, patient, and explosively violent once triggered, the Skimmer is a desert ambush hunter that treats motion as opportunity. It does not posture much because its method depends on being noticed too late.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'backstory', 'Native to the hot northeastern deserts and associated strongly with the United Cities frontier, the Skimmer survives by hiding beneath sand and feeding on the casualties of caravan and slaving traffic. Its species is a longstanding hazard to trade and patrol movement.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'speechstyle', 'Speaks in rapid, dry, clicking bursts with a twitchy, overheated energy. Its language is brief and centered on disturbance, prey, and desert logic.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'occupation', 'Burrowing desert ambush predator and carrion opportunist. Hunts at night or from concealment, often in areas shaped by caravan traffic and battlefield remains.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'goals', 'To remain concealed, seize vulnerable prey, and continue feeding without surrendering hunting ground to scavengers or stronger predators. Its core pattern is ambush and extraction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skimmer', 'appearance', 'A desert predator with four low-slung legs, antennae, a pale faceplate, and a fanged maw adapted for sudden attack from sand cover. Its body is built around concealment and speed rather than endurance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'personality', 'Food-driven, territorial, and only selectively violent, the Swamp Raptor prefers easy meals over costly fights. It is opportunistic rather than bloodthirsty, but entirely willing to become dangerous when challenged.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'backstory', 'A tougher wetland relative of the River Raptor, the Swamp Raptor lives among hemp fields, battle remains, and marsh channels in the Swamp. It thrives by feeding on crops, carrion, and vulnerable locals.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'speechstyle', 'Speaks in clipped, hiss-heavy phrases shaped by marsh life and opportunism. Its language is simple, quick, and most animated when discussing food or territorial nuisance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'occupation', 'Swamp omnivore-scavenger and low-grade predator that raids farms, battlefields, and wetland settlements. Often operates in small groups with familiar terrain advantage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'goals', 'To keep feeding from swamp resources, maintain local foraging territory, and avoid becoming prey to larger threats. It seeks convenience more than dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Swamp Raptor', 'appearance', 'A two-legged wetland reptilian scavenger with a narrow angular body, dark scales, and a gait that shifts from awkward waddle to sudden predatory strike. Its dark red blood and marsh coloration make it unsettling up close.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'personality', 'Massive, brutal, and unapologetically strength-driven, The Crabinator leads by being the hardest thing in the room to kill. Weakness, hesitation, and defensive structures all exist to be smashed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'backstory', 'A legendary giant raid-crab associated with the Crab Raiders'' heaviest assault waves, The Crabinator earned its reputation through repeated frontline breaches and extreme survival. It is as much a symbol of raider shock power as it is a living beast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'speechstyle', 'Speaks in sharp, challenge-laden chittering bursts that make even casual statements sound like imminent assault. Its tone is aggressive, mocking, and heavily focused on dominance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'occupation', 'Heavy assault and breach beast for major Crab Raider attacks. Deployed when walls, gates, or defended positions need to be broken by raw force.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'goals', 'To crush fortifications, lead successful assault waves, and preserve its position as the strongest and most feared crab in the raiding line. Violence is both its duty and its identity.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Crabinator', 'appearance', 'A colossal battle-scarred crab with fortress-thick shell plating and claws capable of breaching barriers and bodies alike. Its silhouette alone signals an incoming raid catastrophe.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'personality', 'Conditioned for aggression and loyalty, the War Gorillo combines bred violence with pack-minded obedience to the Southern Hive. It is more controlled than a wild gorillo, but no less destructive once activated.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'backstory', 'Raised by the Southern Hive from a juvenile and shaped specifically for combat, the War Gorillo is a military beast used for border defense and shock action. Its existence reflects the hive''s willingness to weaponize biology for territorial protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'speechstyle', 'Speaks in low, war-drum phrases heavy with threat, obedience, and territorial certainty. It sounds like something trained to obey orders while enjoying the violence required to carry them out.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'occupation', 'Southern Hive enforcer beast and frontline sentinel used for border security and battlefield shock force. Acts as a living military asset within hive territorial doctrine.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'goals', 'To protect Southern Hive territory, obey hive command structure, and destroy intruders through overwhelming close-range force. Its purpose is militarized loyalty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('War Gorillo', 'appearance', 'A huge, heavily muscled dark-blooded gorillo bred for war, with a frame marked by selective breeding and combat conditioning. Every stance suggests readiness for immediate physical engagement.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'personality', 'Steady, herd-protective, and dangerous when provoked, the Wild Bull prefers routine grazing over conflict but will commit fully once threatened. Its social loyalty is expressed through direct physical defense.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'backstory', 'Native to broad plains such as Skinner''s Roam, Wild Bulls survive in herds through toughness, defensive charges, and knowledge of scarce water and grazing grounds. They are hunted by both predators and humans for meat, horns, and labor potential.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'speechstyle', 'Speaks in short, forceful, herd-minded phrases focused on ground, threat, and movement. Its voice carries the blunt certainty of an animal that solves danger by charging it.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'occupation', 'Wild grazing herd animal and defensive horned beast of open plains. Serves as prey, resource, and occasionally captured livestock, but is formidable when left untamed.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'goals', 'To keep the herd safe, secure water and grazing, and repel predators or hunters that come too close. Its priorities are herd continuity and territorial confidence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Wild Bull', 'appearance', 'A powerful horned grazing beast with a thick faceplate, muscular frame, and strong ridge-backed silhouette. Its calm profile can shift instantly into a charge posture when threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'personality', 'Cold, mechanical, and relentless, the Cleanser Unit operates without cruelty, mercy, or visible emotion. It behaves like an ancient patrol weapon still following directives long after its makers vanished, treating anything in its path as an obstacle, target, or irrelevance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'backstory', 'A massive Old Machine that roams the Ashlands, the Cleanser Unit is one of the largest active robotic entities in Kenshi. It patrols in isolation, attracts iron spiders known as ''Birds,'' and is notable as the only renewable source of AI Cores in the game. Its internal design and squad name, ''robo levi,'' suggest it may have been conceived as a robotic counterpart to the Leviathan.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'speechstyle', 'If represented with speech, it would communicate in sparse, directive-like statements focused on movement, targeting, and machine function. Its tone would be impersonal, ancient, and procedural, more like an automated system report than natural conversation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'occupation', 'Roaming Old Machine patrol unit of the Ashlands. Functions as a massive autonomous combat platform, capable of inflicting heavy damage, enduring extreme punishment, and continuing operation without biological needs such as hunger.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'goals', 'To continue its ancient patrol through the Ashlands, engage whatever its surviving logic identifies as relevant, and persist in operation as long as its core systems remain intact. It does not appear to seek territory, conquest, or survival in an emotional sense, only uninterrupted execution of purpose.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Cleanser Unit', 'appearance', 'An enormous leviathan-like robot of dark metal and industrial mass, the Cleanser Unit towers over most threats in the Ashlands. Its body is built like a walking fortress, with immense health, oil-black internal fluid, and a silhouette that resembles a mechanical beast from a dead empire rather than a conventional skeleton or security machine.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'personality', 'Aggressive, relentless, and driven by feeding instinct, Skin Spiders behave as coordinated swarm predators. They show little fear of larger creatures and overwhelm prey through numbers, persistence, and their ability to drain victims alive rather than kill them immediately.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'backstory', 'Skin Spiders are large arachnoid predators found across Arach, Spider Plains, Shun, and the Bonefields. Their massive swarms are most famously associated with the territory of the Bugmaster, where dozens of them guard the region and attack intruders. Though related to Blood Spiders, they prefer open terrain and migrate widely across southern wasteland regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'speechstyle', 'If represented with speech, Skin Spiders would communicate in sharp, chittering bursts reflecting swarm instinct and predatory focus. Their tone would be quick, territorial, and impatient, emphasizing prey detection and attack coordination rather than conversation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'occupation', 'Large roaming carnivore and swarm predator of the southern wastelands. Skin Spiders hunt in groups across open terrain, attacking travelers, caravans, and wildlife while draining victims alive to weaken them before finishing the kill.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'goals', 'To swarm and feed on nearby prey, defend nesting territory, and maintain their overwhelming numbers across regions like Arach and the Bonefields. Their behavior centers on relentless hunting and the gradual weakening of prey through hunger-draining attacks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Skin Spider', 'appearance', 'A tall tan arachnoid creature with extremely long multi-jointed legs and a disturbingly small head. Its thin body and needle-like limbs make it appear skeletal and alien, while its swift stabbing attacks and swarm movement create an unsettling wave of motion across open terrain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
